-- Generated by sql/tools/gen_start_quests.py (change m6-start-quests): new race/class pairs borrow the
-- Warrior's starting-zone class quests; autocomplete = given or ended by a class trainer. Idempotent.
CREATE TABLE IF NOT EXISTS `arpg_quest_proxy` (
  `quest` INT UNSIGNED NOT NULL, `race` TINYINT UNSIGNED NOT NULL, `class` TINYINT UNSIGNED NOT NULL,
  `autocomplete` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`quest`, `race`, `class`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='m6-start-quests: quests a new race/class pair may take (Warrior proxy)';
DELETE FROM `arpg_quest_proxy`;
